def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each motif is a five-cell diamond: center plus its four diagonal neighbors.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] == 0 and
                grid[r-1][c] == 2 and grid[r+1][c] == 2 and
                grid[r][c-1] == 2 and grid[r][c+1] == 2):
                centers.append((r, c))
    # Join diamonds whose centers share a row or column, filling only the gap.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i+1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 2, max(c1, c2) - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2:
                for r in range(min(r1, r2) + 2, max(r1, r2) - 1):
                    if out[r][c1] == 0:
                        out[r][c1] = 1
    return out

